#include "../../04-图论/二分图最小点覆盖.cpp"
pair<vector<int>,vector<int>> vertex_cover(const vector<vector<int>> &arg_adj,const vector<int> &arg_match){adj=arg_adj;match=arg_match;return vertex_cover();}
int main(){mt19937 g(129);for(int z=0;z<600;z++){int nl=g()%6,nr=g()%6;vector<vector<int>>a(nl+1);for(int u=1;u<=nl;u++)for(int v=1;v<=nr;v++)if(g()%2)a[u].push_back(v);int best=-1;vector<int>match(nr+1),cur(nr+1);auto dfs=[&](auto&&self,int u,int cnt)->void{if(u>nl){if(cnt>best)best=cnt,match=cur;return;}self(self,u+1,cnt);for(int v:a[u])if(!cur[v]){cur[v]=u;self(self,u+1,cnt+1);cur[v]=0;}};dfs(dfs,1,0);auto [l,r]=vertex_cover(a,match);assert(int(l.size()+r.size())==best);vector<int>vl(nl+1),vr(nr+1);for(int u:l)vl[u]=1;for(int v:r)vr[v]=1;for(int u=1;u<=nl;u++)for(int v:a[u])assert(vl[u]||vr[v]);int minimum=nl+nr;for(int mask=0;mask<(1<<(nl+nr));mask++){bool ok=true;for(int u=1;u<=nl;u++)for(int v:a[u])if(!(mask>>(u-1)&1)&&!(mask>>(nl+v-1)&1))ok=false;if(ok)minimum=min(minimum,__builtin_popcount(unsigned(mask)));}assert(best==minimum);}cout<<"cover OK\n";}
